fn test_lex_single_quoted_strings() {
    assert_tokenize_eq_roundtrip!(
        "'ab' 'multi word' '../ivm/catch.ts'",
        Token::new(
            TokenType::Literal,
            4,
            Some(LiteralType::String {
                is_terminated: true
            })
        ),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(
            TokenType::Literal,
            12,
            Some(LiteralType::String {
                is_terminated: true
            })
        ),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(
            TokenType::Literal,
            17,
            Some(LiteralType::String {
                is_terminated: true
            })
        ),
    );
}

#[test]
fn test_lex_regex_literals() {
    assert_tokenize_eq_roundtrip!(
        "/abc/ (/def/.exec(input)) / value",
        // regex literal /abc/
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::RegexString { has_flags: false })
        ),
        // grouping parentheses
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::OpenParenthesis, 1, None),
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::RegexString { has_flags: false })
        ),
        Token::new(TokenType::Dot, 1, None),
        Token::new(TokenType::Identifier, 4, None),
        Token::new(TokenType::OpenParenthesis, 1, None),
        Token::new(TokenType::Identifier, 5, None),
        Token::new(TokenType::CloseParenthesis, 1, None),
        Token::new(TokenType::CloseParenthesis, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Divide, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 5, None),
    );
}

#[test]
fn test_lex_regex_literals_with_flags() {
    assert_tokenize_eq_roundtrip!(
        "/foo/gi\n/bar/m",
        Token::new(
            TokenType::Literal,
            7,
            Some(LiteralType::RegexString { has_flags: true })
        ),
        Token::new(TokenType::Newline, 1, None),
        Token::new(
            TokenType::Literal,
            6,
            Some(LiteralType::RegexString { has_flags: true })
        ),
    );
}

#[test]
fn test_lex_regex_literal_in_context() {
    assert_tokenize_eq_roundtrip!(
        "a == /foo/gi.test",
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Equal, 2, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(
            TokenType::Literal,
            7,
            Some(LiteralType::RegexString { has_flags: true })
        ),
        Token::new(TokenType::Dot, 1, None),
        Token::new(TokenType::Identifier, 4, None),
    );
}

#[test]
fn test_lex_regex_literal_in_tree() {
    assert_tokenize_eq_roundtrip!(
        r"
<input
    type=/text/i
    // comment
/>",
        Token::new(TokenType::Newline, 1, None),
        Token::new(TokenType::LessThan, 1, None),
        Token::new(TokenType::Identifier, 5, None),
        Token::new(TokenType::Newline, 1, None),
        Token::new(TokenType::Whitespace, 4, None),
        Token::new(TokenType::Identifier, 4, None),
        Token::new(TokenType::Assign, 1, None),
        // `/text/i` is a real regex literal
        Token::new(
            TokenType::Literal,
            7,
            Some(LiteralType::RegexString { has_flags: true })
        ),
        Token::new(TokenType::Newline, 1, None),
        Token::new(TokenType::Whitespace, 4, None),
        Token::new(TokenType::LineComment, 10, None),
        Token::new(TokenType::Newline, 1, None),
        // `/>` is a tag end, so this should become Divide + GreaterThan (instead of RegexLiteral)
        Token::new(TokenType::Divide, 1, None),
        Token::new(TokenType::GreaterThan, 1, None),
    );
}

